// On importe Cheerio (inclus dans n8n)
const cheerio = require('cheerio');

// On récupère le HTML renvoyé par le noeud précédent (HTTP Request)
// Note: Assurez-vous que "Response Format" du HTTP Request est bien sur "String"
const html = $input.item.json.data || Object.values($input.item.json)[0]; 

const $ = cheerio.load(html);
const matches = [];

// Date du jour pour l'affichage
const today = new Date().toISOString().split('T')[0];

try {
    // Sélecteurs pour Elbotola.com (à adapter si le site change)
    // On cherche les lignes de match
    $('.matchs_group .match_row').each((i, el) => {

        let homeTeam = $(el).find('.club_name_home').text().trim();
        let awayTeam = $(el).find('.club_name_away').text().trim();
        let score = $(el).find('.result').text().trim(); // Ex: "1 - 0"
        let time = $(el).find('.match_time').text().trim(); // Ex: "20:00" ou "90'"

        // Si on a des noms d'équipes, c'est un match valide
        if (homeTeam && awayTeam) {

            let status = 'UPCOMING';

            // Logique pour déterminer le statut
            if (score.includes('-')) {
                // Si le temps contient des minutes (ex: 35') ou "Live", c'est en direct
                if (time.includes("'") || $(el).html().includes('live')) {
                    status = 'LIVE';
                } else {
                    status = 'FINISHED';
                }
            } else {
                // Pas de tiret dans le score = Pas encore commencé
                status = 'UPCOMING';
                score = 'vs'; // On affiche "vs" au lieu de vide
            }

            matches.push({
                home: homeTeam,
                away: awayTeam,
                score: score.replace(/\s+/g, ''), // Nettoie le score
                time: time,
                status: status,
                date: today
            });
        }
    });

} catch (error) {
    console.log("Erreur de parsing : " + error.message);
}

// === FILE DE SECURITÉ ===
// Si le site a changé ou bloque le scraping, on envoie des fausses données
// pour ne pas casser votre site web.
if (matches.length === 0) {
    return [
        {
            home: "Raja CA (Test)", 
            away: "Wydad AC", 
            score: "0 - 0", 
            time: "20:00", 
            status: "UPCOMING", 
            date: today
        },
        {
            home: "RS Berkane", 
            away: "FUS Rabat", 
            score: "Live", 
            time: "En direct", 
            status: "LIVE", 
            date: today
        }
    ];
}

return matches;
